(function(scope){
 const regions=[['us','美國',-100,39,/美國|美方|聯準會|白宮|川普|特朗普|\b(?:US|USA|United States|Fed|Trump|America|American)\b/i],['europe','歐洲',12,50,/歐洲|歐盟|英國|德國|法國|\b(?:Europe|European|Britain|British|Germany|France|EU)\b/i],['asia','亞洲',112,32,/亞洲|中國|台灣|臺灣|日本|韓國|印度|\b(?:Asia|China|Chinese|Taiwan|Japan|India|Korea)\b/i],['middleeast','中東',44,29,/中東|以色列|伊朗|沙烏地|\b(?:Middle East|Israel|Iran|Saudi)\b/i],['africa','非洲',21,0,/非洲|肯亞|奈及利亞|\b(?:Africa|Kenya|Nigeria)\b/i],['latam','拉丁美洲',-65,-15,/拉美|拉丁美洲|巴西|墨西哥|\b(?:Latin America|Brazil|Mexico)\b/i],['oceania','大洋洲',135,-25,/澳洲|紐西蘭|\b(?:Australia|New Zealand)\b/i]];
 const taipeiDate=value=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
 const iso=date=>date.toISOString().slice(0,10);
 const weekStart=value=>{const d=new Date(value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-d.getUTCDay());return iso(d)};
 function collect(list){const unique=new Map();for(const issue of list)for(const entry of issue.entries||[]){const id=entry.id||JSON.stringify([entry.date,entry.text,entry.links]);let existing=unique.get(id);if(!existing){existing={...entry,id,topics:[]};unique.set(id,existing)}else if(entry.updatedAt&&(!existing.updatedAt||entry.updatedAt>existing.updatedAt)){const relations=existing.topics;Object.assign(existing,entry,{topics:relations})}if(!existing.topics.some(t=>t.id===issue.id))existing.topics.push({id:issue.id,name:issue.name})}return [...unique.values()].map(e=>({...e,title:e.title?.trim()||String(e.text||'').split('\n').map(s=>s.trim()).filter(Boolean).find(s=>!/^[[［【].{1,12}[\]］】](?:\p{Emoji_Presentation}|\s)*$/u.test(s))||'未命名記事',statDate:e.createdAt?taipeiDate(e.createdAt):e.date,regionIds:inferRegions(e)})).sort((a,b)=>String(b.statDate).localeCompare(String(a.statDate))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
 const countries=typeof ReviewCountries!=='undefined'?ReviewCountries:(typeof require!=='undefined'?require('./review-countries.js'):[]);
 function inferRegions(entry){if(entry.country&&entry.country!=='auto')return [entry.country];if(entry.region&&entry.region!=='auto')return [entry.region];const heading=String(entry.text||'').split('\n')[0];const bracket=heading.match(/^[\[［【]([^\]］】]+)[\]］】]/);const content=bracket?bracket[1]:String(entry.title||'')+' '+String(entry.text||'');const lower=content.toLowerCase();const matched=countries.filter(c=>c.aliases.some(alias=>{const term=alias.toLowerCase();if(!/^[a-z\s.'’()-]+$/i.test(alias))return lower.includes(term);let at=lower.indexOf(term);while(at>=0){if(!/[a-z]/i.test(lower[at-1]||'')&&!/[a-z]/i.test(lower[at+term.length]||''))return true;at=lower.indexOf(term,at+term.length)}return false})).map(c=>c.id);if(matched.length)return matched;const direct=regions.filter(r=>r[4].test(content));return direct.length?direct.map(r=>r[0]):['global']}
 function searchable(note,query){const haystack=[note.title,note.text,...(note.topics||[]).map(t=>t.name),...(note.links||[]).flatMap(l=>[l.title,l.url]),...(note.regionIds||[]).map(id=>countries.find(c=>c.id===id)?.name||regions.find(r=>r[0]===id)?.[1]||'全球')].join(' ').toLowerCase();return query.trim().toLowerCase().split(/\s+/).filter(Boolean).every(part=>haystack.includes(part))}
 function inWeek(note,start){if(start==='all')return true;const end=new Date(start+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+7);return note.statDate>=start&&note.statDate<iso(end)}
 function options(notes,today){const current=weekStart(today),oldest=notes.reduce((a,n)=>n.statDate&&n.statDate<a?n.statDate:a,today),limit=weekStart(oldest);const out=[];for(let d=new Date(current+'T00:00:00Z'),i=0;iso(d)>=limit&&i<520;i++,d.setUTCDate(d.getUTCDate()-7))out.push(iso(d));const previous=new Date(current+'T00:00:00Z');previous.setUTCDate(previous.getUTCDate()-7);if(!out.includes(iso(previous)))out.push(iso(previous));return out}
 const api={regions,countries,searchable,taipeiDate,weekStart,collect,inWeek,options,iso,inferRegions};scope.ReviewModel=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
